/* Microfix 3.8.45: reliable theme control and screenshot capture fallback. */
globalThis.bcCaptureBriefCraftViewport45=async function(){
  try{const dataUrl=await chrome.tabs.captureVisibleTab(undefined,{format:"png"});if(dataUrl)return{ok:true,dataUrl}}catch{}
  let stream=null;
  try{
    stream=await navigator.mediaDevices.getDisplayMedia({video:{displaySurface:"browser"},audio:false,preferCurrentTab:true,selfBrowserSurface:"include",surfaceSwitching:"exclude"});
    const video=document.createElement("video");video.muted=true;video.playsInline=true;video.srcObject=stream;await video.play();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
    const canvas=document.createElement("canvas");canvas.width=Math.max(1,video.videoWidth||innerWidth);canvas.height=Math.max(1,video.videoHeight||innerHeight);canvas.getContext("2d").drawImage(video,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL("image/png");return{ok:true,dataUrl}
  }catch(error){return{ok:false,error:error?.message||"Не удалось сделать снимок"}}
  finally{stream?.getTracks?.().forEach(track=>track.stop())}
};
(()=>{
  const bind=id=>{const button=document.getElementById(id);if(!button||button.dataset.bcTheme45)return;button.dataset.bcTheme45="1";button.addEventListener("click",event=>{event.preventDefault();event.stopImmediatePropagation();state.theme=state.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=state.theme;applyTheme();queuePersist()},true)};
  bind("workspaceTheme");bind("welcomeTheme");document.documentElement.dataset.theme=state.theme;applyTheme()
})();

